// Core14Table is the compiled reduction of Adobe's AFM files for the fourteen
// standard fonts of ISO 32000-1 section 9.6.2.2 (read): per font its ascender,
// descender and bounding box, and per glyph its name, its code in the font's
// built-in encoding and its width in thousandths of an em. The arrays are
// generated by build/fonts/core14.py from third_party/core14/, whose files
// build/fonts/core14.lock pins by SHA-256, and the table's digest is recorded
// beside it so a hand edit is found.

#ifndef PDFKIT_FONTS_GENERATED_CORE14_TABLE_HPP
#define PDFKIT_FONTS_GENERATED_CORE14_TABLE_HPP

#include <cstdint>
#include <span>
#include <string_view>

namespace pdfkit::fonts::generated {

class Core14Table {
 public:
  struct Font {
    std::string_view name;
    std::int16_t ascender = 0;
    std::int16_t descender = 0;
    // llx, lly, urx, ury.
    std::int16_t bbox[4] = {0, 0, 0, 0};
    // The font's glyphs are glyphs()[first, first + count), sorted by name.
    std::uint16_t first = 0;
    std::uint16_t count = 0;
  };

  struct Glyph {
    std::string_view name;
    // The code in the font's built-in encoding, or -1 when unencoded.
    std::int16_t code = -1;
    std::int16_t width = 0;
  };

  // The fourteen fonts in the order of ISO 32000-1 section 9.6.2.2.
  [[nodiscard]] static std::span<const Font> fonts() noexcept;
  [[nodiscard]] static std::span<const Glyph> glyphs() noexcept;

  // The SHA-256 the generator computed over the table's canonical lines: per
  // font "F name ascender descender llx lly urx ury count", then per glyph
  // "name code width", each with a line feed.
  [[nodiscard]] static std::string_view content_sha256() noexcept;
};

}  // namespace pdfkit::fonts::generated

#endif  // PDFKIT_FONTS_GENERATED_CORE14_TABLE_HPP
